const item = $input.first().json;
const body = item.body || {};
const query = item.query || {};
const headers = item.headers || {};

// operation from body OR query (never call it 'action')
const operation = String(body.operation || query.operation || 'unknown').trim();

// Real caller number from the phone system (header/body), never an LLM example
const rawCaller = headers['x-caller-number'] || headers['x-caller-id'] || headers['x-placetel-caller'] || body.phone || body.caller || body.from || body.caller_number || query.phone || query.caller || '';

// Normalise to the national significant number (Germany): strip +, 00,
// the country code 49, or a national leading 0. Pipedrive stores numbers
// nationally (0162...) or internationally (+49162...); this matches both.
let caller = String(rawCaller).replace(/[^\d+]/g, '').replace(/^\+/, '');
if (caller.startsWith('00')) caller = caller.slice(2);
if (caller.startsWith('49')) caller = caller.slice(2);
else if (caller.startsWith('0')) caller = caller.slice(1);

return [{ json: { operation, callerNumber: caller, callerRaw: String(rawCaller), body, query } }];

const raw = $input.first() ? $input.first().json : {};
const j = raw.item || raw;
const p = $('Parse Request').first().json;
const found = !!(j && j.id);
const name = j.name || 'there';
const out = found
  ? { operation: 'check_customer', found: true, person_id: j.id, name: j.name || null, org: j.org_name || null, speech: `I found your record, ${name}. How can I help you today?` }
  : { operation: 'check_customer', found: false, callerNumber: p.callerNumber, speech: `I could not find a contact for your number. I can create one for you if you like.` };
return [{ json: out }];

const raw = $input.first() ? $input.first().json : {};
const j = raw.item || raw;
const ok = !!(j && j.id);
return [{ json: { operation: 'create_contact', created: ok, person_id: ok ? j.id : null, name: ok ? j.name : null, speech: ok ? `Thank you ${j.name}. I have created your contact.` : `I am sorry, I could not create your contact right now.` } }];

