const p = $('Parse Request').first().json;
const ok = !!(j && j.id);
return [{ json: { operation: 'create_callback', created: ok, activity_id: ok ? j.id : null, speech: ok ? `Your callback has been scheduled. A colleague will call you back at ${p.callerNumber}.` : `I am sorry, I could not schedule your callback right now.` } }];

const raw = $input.first() ? $input.first().json : {};
const j = raw.item || raw;
const p = $('Parse Request').first().json;
const found = !!(j && j.id);
const id = found ? j.id : (p.body.deal_id || p.body.id);
const status = j.status || null;
const title = j.title || 'your deal';
const map = { open: 'open and in progress', won: 'won and closed', lost: 'closed as lost', deleted: 'no longer active' };
const val = (j.value != null && j.value !== 0 && j.currency) ? ` It is valued at ${j.value} ${j.currency}.` : '';
return [{ json: { operation: 'deal_status', found: found, deal_id: id, status: status, speech: found ? `Your deal "${title}" is currently ${map[status] || status || 'open'}.${val}` : `I could not find a deal with the number ${id}.` } }];

const raw = $input.first() ? $input.first().json : {};
const j = raw.item || raw;
const ok = !!(j && j.id);
return [{ json: { operation: 'create_deal', created: ok, deal_id: ok ? j.id : null, speech: ok ? `I have logged your request. Your reference number is ${j.id}. A colleague will follow up with you.` : `I am sorry, I could not log your request right now. Let me take your details first.` } }];

